l3-closure:
function criarContador() {
  let contagem = 0;
  return function () {
    contagem++;
    return contagem;
  };
}

l12-cosseno:
function cosseno(a, b) {
  let escalar = 0, ma = 0, mb = 0;
  for (let i = 0; i < a.length; i++) {
    escalar += a[i] * b[i];
    ma += a[i] * a[i];
    mb += b[i] * b[i];
  }
  return escalar / (Math.sqrt(ma) * Math.sqrt(mb));
}

l13-binaria:
function buscaBinaria(v, alvo) {
  let inicio = 0, fim = v.length - 1;
  while (inicio <= fim) {
    const meio = Math.floor((inicio + fim) / 2);
    if (v[meio] === alvo) return meio;
    if (v[meio] < alvo) inicio = meio + 1;
    else fim = meio - 1;
  }
  return -1;
}
